"""reports/results.json and docs/REPORT.md, generated from exported runs and proofs. Do not edit."""

from __future__ import annotations

import json
import math
from datetime import UTC, datetime
from decimal import Decimal
from pathlib import Path

from . import stats
from .config import ROOT, load, reports_dir


def runs_dir():
    return reports_dir() / "runs"


def export(conn, run_id: str) -> Path:
    from . import store

    rows = store.attempts(conn, run_id)
    run = conn.execute("SELECT * FROM aeh.runs WHERE id = %s", (run_id,)).fetchone()
    data = {
        "run": run_id,
        "task_set": run["task_set"],
        "budget_usd": float(run["budget_usd"]),
        "config": run["config"],
        "ledger": store.ledger_check(conn, run_id),
        "attempts": [
            {
                k: (float(v) if isinstance(v, Decimal) else v.isoformat() if hasattr(v, "isoformat") else v)
                for k, v in r.items()
                if k not in ("worker", "lease_until")
            }
            for r in rows
        ],
    }
    runs_dir().mkdir(parents=True, exist_ok=True)
    out = runs_dir() / f"{run_id}.json"
    out.write_text(json.dumps(data, indent=1))
    return out


def _load(p: Path):
    return json.loads(p.read_text()) if p.exists() else None


def collect() -> dict:
    cfg = load("report")
    proofs = {s: _load(reports_dir() / "proofs" / f"{s}.json") for s in ("dev", cfg["heldout_set"])}
    dev_attempts, dev_ledgers = [], []
    for r in cfg["dev_runs"]:
        d = _load(runs_dir() / f"{r}.json")
        if d:
            dev_attempts += d["attempts"]
            dev_ledgers.append({"run": r, **d["ledger"]})
    first = _load(reports_dir() / "heldout" / "first_run.json")
    return {
        "generated_at": datetime.now(UTC).isoformat(),
        "proofs": {k: v["summary"] | {"tasks_detail": v["tasks"]} if v else None for k, v in proofs.items()},
        "dev": stats.summarize(dev_attempts) | {"ledgers": dev_ledgers} if dev_attempts else None,
        "heldout": first,
        "setups": load("setups")["setups"],
        "decision_rule": load("decision"),
    }


def _pct(x) -> str:
    return "n/a" if x is None or (isinstance(x, float) and math.isnan(x)) else f"{100 * x:.0f}%"


def _usd(x) -> str:
    return "n/a" if x is None or x == math.inf else f"${x:.2f}"


def markdown(r: dict) -> str:
    out = [f"# Report\n\nGenerated by `aeh report` ({r['generated_at']}). Do not edit.\n"]
    for name, p in r["proofs"].items():
        if not p:
            continue
        out.append(
            f"## Graders, {name} set\n\n{p['proven']} of {p['tasks']} tasks proven: the task state fails the hidden tests and passes its own "
            f"suite, the reference change is accepted, and {p['mutants_caught']} of {p['mutants']} wrong changes are caught. "
            f"Unmergeable changes that pass the tests: {p['unmergeable_rejected']} of {p['unmergeable']} rejected "
            f"({', '.join(f'{k} {v}' for k, v in p['unmergeable_rejected_by'].items() if v)}). The review judge passed "
            f"{p['judge_passes_references']} reference changes.\n"
        )
    d = r["dev"]
    if d:
        lines = [
            "| Setup | Attempts | Tests pass | Accepted | Rejected after tests pass | Cost per attempt | Cost per accepted change | Median minutes |",
            "|---|---:|---:|---:|---:|---:|---:|---:|",
        ]
        for s, x in d["setups"].items():
            a, t, c = x["accepted"], x["tests_pass"], x["cost_per_accepted"]
            lines.append(
                f"| {s} | {x['attempts']} | {_pct(t['rate'])} | {_pct(a['rate'])} ({_pct(a['lo'])}-{_pct(a['hi'])}) | "
                f"{x['rejected_after_tests_pass']} of {x['tests_pass_count']} | {_usd(x['cost_usd_per_attempt'])} | "
                f"{_usd(c.get('point'))} ({_usd(c.get('lo'))}-{_usd(c.get('hi'))}) | {x['median_minutes']} |"
            )
        diffs = "\n".join(
            f"- {s}: {v['diff']:+.0%} accepted (interval {v['lo']:+.0%} to {v['hi']:+.0%}, {v['tasks']} tasks)"
            for s, v in d["vs_baseline"].items()
            if v.get("tasks")
        )
        aa = "\n".join(
            f"- {s}: sample 2 minus sample 1 {v['diff']:+.0%} (interval {v['lo']:+.0%} to {v['hi']:+.0%})"
            for s, v in d["aa"].items()
            if v.get("tasks")
        )
        out.append(
            f"## Benchmark on the dev tasks\n\nIntervals are {int(100 * d['confidence'])}% bootstrap intervals over tasks.\n\n"
            + "\n".join(lines)
            + f"\n\nAgainst the baseline, paired by task:\n\n{diffs or '- none'}\n\nNoise floor (the same setup against itself):\n\n{aa or '- needs two samples'}\n\n"
            f"**Decision:** {d['decision']['choice']}: {d['decision']['why']}.\n"
        )
        for led in d.get("ledgers", []):
            out.append(
                f"Budget {led['run']}: ${led['committed_usd']:.2f} committed of ${led['budget_usd']:.2f}; within budget: {led['within_budget']}; "
                f"spend log matches the record: {led['open_reservations_match'] and led['settled_match']}.\n"
            )
    h = r["heldout"]
    if h:
        out.append(
            f"## Held-out tasks, first run (kept as recorded)\n\nWritten by someone who never saw the harness. Recorded {h['recorded_at']}.\n\n"
            + "\n".join(
                f"- {s}: accepted {x['accepted']} of {x['attempts']}, tests pass {x['tests_pass']}, cost ${x['cost_usd']:.2f}"
                for s, x in h["setups"].items()
            )
            + "\n"
        )
    return "\n".join(out)


def clean(o):
    """JSON without Infinity or NaN (the dashboard reads it with JSON.parse)."""
    if isinstance(o, float) and (math.isinf(o) or math.isnan(o)):
        return None
    if isinstance(o, dict):
        return {k: clean(v) for k, v in o.items()}
    if isinstance(o, list | tuple):
        return [clean(v) for v in o]
    return o


def write() -> dict:
    r = collect()
    reports_dir().mkdir(parents=True, exist_ok=True)
    (reports_dir() / "results.json").write_text(json.dumps(clean(r), indent=1, default=str))
    (ROOT / "docs" / "REPORT.md").write_text(markdown(r))
    return r
